    public CheckPointType invokeStrategyV2(PropertyManagerVO propertyManager, List<StrategyManagerVO> strategyManagers, JSONObject origin) {
        if (propertyManager.getType().equals(PropertyType.Add.getType())) {
            for(StrategyManagerVO strategyManager : strategyManagers) {
                Object res = this.expressionImplement(strategyManager, origin, propertyManager);
                if (res != null) {
                    origin.put(propertyManager.getName(), res);
                }
            }
        }

        if (propertyManager.getType().equals(PropertyType.APPEND.getType())) {
            List<String> tags = new ArrayList();

            for(StrategyManagerVO strategyManager : strategyManagers) {
                String res = (String)this.expressionImplement(strategyManager, origin, propertyManager);
                if (org.apache.commons.lang.StringUtils.isNotEmpty(res)) {
                    tags.add(res);
                }
            }

            String result = org.apache.commons.lang.StringUtils.join(tags.toArray(), propertyManager.getSeparatorName());
            origin.put(propertyManager.getName(), result);
        }

        if (propertyManager.getType().equals(PropertyType.Together.getType())) {
            for(StrategyManagerVO strategyManager : strategyManagers) {
                Object res = this.expressionImplement(strategyManager, origin, propertyManager);
                if (res != null) {
                    if (CheckPointType.CheckPointEnd.getType().equals(res)) {
                        return CheckPointType.CheckPointEnd;
                    }

                    origin.put(strategyManager.getName(), res);
                }
            }
        }

        return CheckPointType.CheckPointFinished;
